plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}

CFBundleIdentifier
com.albinanto.elterminalo
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile

LSMinimumSystemVersion
12.0
NSHighResolutionCapable
true
NSHumanReadableCopyright
{{.Info.Copyright}}

NSDesktopFolderUsageDescription
ElTerminalo runs the shell commands you type, which may read or write files on your Desktop.
NSDocumentsFolderUsageDescription
ElTerminalo runs the shell commands you type, which may read or write files in your Documents folder.
NSDownloadsFolderUsageDescription
ElTerminalo runs the shell commands you type, which may read or write files in your Downloads folder.
NSRemovableVolumesUsageDescription
ElTerminalo runs the shell commands you type, which may read or write files on removable volumes.
NSNetworkVolumesUsageDescription
ElTerminalo runs the shell commands you type, which may read or write files on network volumes.
NSFileProviderDomainUsageDescription
ElTerminalo runs the shell commands you type, which may read or write files synced by iCloud Drive and other file providers.
{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions

      {{.Ext}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        com.albinanto.elterminalo.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
